import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.copy(config.scenePosition || new THREE.Vector3(0, 0, 0));

  const timelines = [];
  const meshes = [];
  const materials = [];

  // Color palette
  const colorBg = '#0b0b10';
  const colorSurface = '#14141a';
  const colorInk = '#16161d';
  const colorPaper = '#e8ecf2';
  const colorAccent = '#ff2a38';

  // Background plane (7 x 5.5 at z=0)
  const backgroundGeom = new THREE.PlaneGeometry(7, 5.5);
  const backgroundMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(colorBg),
    side: THREE.FrontSide
  });

  const backgroundMesh = new THREE.Mesh(backgroundGeom, backgroundMat);
  backgroundMesh.position.z = -0.1;
  group.add(backgroundMesh);
  meshes.push(backgroundMesh);
  materials.push(backgroundMat);

  // Text blocks configuration
  const textBlocks = [
    {
      text: 'NOVA ATELIER / JOURNAL',
      fontFamily: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 700,
      letterSpacing: 0.12,
      position: [-3.1, 1.7, 0],
      uppercase: true
    },
    {
      text: 'PRECISION IS',
      fontFamily: 'Lora',
      fontSize: 124,
      fontWeight: 600,
      letterSpacing: -0.015,
      position: [-3.1, 0.9, 0]
    },
    {
      text: 'A HABIT.',
      fontFamily: 'Lora',
      fontSize: 124,
      fontWeight: 600,
      letterSpacing: -0.015,
      position: [-3.1, 0.25, 0]
    },
    {
      text: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
      fontFamily: 'JetBrains Mono',
      fontSize: 26,
      fontWeight: 400,
      letterSpacing: 0,
      position: [-3.1, -0.8, 0]
    },
    {
      text: 'ISSUE 12 / JULY 2026',
      fontFamily: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      position: [-3.1, -1.9, 0]
    }
  ];

  // Create text meshes via fontAtlas
  const textMeshes = [];

  textBlocks.forEach((block) => {
    const textMesh = ctx.fontAtlas.createText({
      text: block.uppercase ? block.text.toUpperCase() : block.text,
      fontFamily: block.fontFamily,
      fontSize: block.fontSize,
      fontWeight: block.fontWeight,
      letterSpacing: block.letterSpacing,
      color: colorPaper
    });

    if (textMesh) {
      textMesh.position.set(...block.position);
      textMesh.userData.origY = block.position[1];
      group.add(textMesh);
      textMeshes.push(textMesh);
      meshes.push(textMesh);
    }
  });

  // Create letterpress shadow for hero text (0.02 units behind at #16161d)
  if (textMeshes.length > 1) {
    const hero1Shadow = ctx.fontAtlas.createText({
      text: 'PRECISION IS',
      fontFamily: 'Lora',
      fontSize: 124,
      fontWeight: 600,
      letterSpacing: -0.015,
      color: colorInk
    });
    if (hero1Shadow) {
      hero1Shadow.position.set(-3.1, 0.9, -0.02);
      group.add(hero1Shadow);
      meshes.push(hero1Shadow);
    }
  }

  if (textMeshes.length > 2) {
    const hero2Shadow = ctx.fontAtlas.createText({
      text: 'A HABIT.',
      fontFamily: 'Lora',
      fontSize: 124,
      fontWeight: 600,
      letterSpacing: -0.015,
      color: colorInk
    });
    if (hero2Shadow) {
      hero2Shadow.position.set(-3.1, 0.25, -0.02);
      group.add(hero2Shadow);
      meshes.push(hero2Shadow);
    }
  }

  // Accent underline rule: 2.2 x 0.05 units at #ff2a38, emissive 1.2, at y=-0.15
  const ruleGeom = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(colorAccent),
    emissive: new THREE.Color(colorAccent),
    emissiveIntensity: 1.2
  });
  const ruleMesh = new THREE.Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(-3.1 + 1.1, -0.15, 0.01);
  ruleMesh.scale.x = 0;
  group.add(ruleMesh);
  meshes.push(ruleMesh);
  materials.push(ruleMat);

  // Animation timeline
  const mainTimeline = gsap.timeline();
  timelines.push(mainTimeline);

  // Background fade in
  mainTimeline.from(backgroundMesh, {
    opacity: 0,
    duration: 0.3
  }, 0);

  // Text blocks: rise-in (y +0.4 to 0, opacity 0 to 1, 700ms power3.out) with 80ms stagger
  let staggerDelay = 0;
  textMeshes.forEach((mesh) => {
    mainTimeline.from(mesh, {
      y: mesh.userData.origY + 0.4,
      opacity: 0,
      duration: 0.7,
      ease: 'power3.out'
    }, staggerDelay);
    staggerDelay += 0.08;
  });

  // Rule draws (scaleX 0 to 1) over 500ms after hero lands
  mainTimeline.to(ruleMesh.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.inOut'
  }, 0.7);

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach(tl => tl.kill());

    // Dispose geometries
    backgroundGeom.dispose();
    ruleGeom.dispose();

    // Dispose materials
    materials.forEach(mat => mat.dispose());

    // Dispose text meshes (they may have their own materials/textures)
    meshes.forEach(mesh => {
      if (mesh.geometry && typeof mesh.geometry.dispose === 'function') {
        mesh.geometry.dispose();
      }
      if (mesh.material && typeof mesh.material.dispose === 'function') {
        mesh.material.dispose();
      }
    });
  };

  group.userData.handlers = {};

  return group;
}
